/**
 * Online status. The player chooses a mode; friends see a status derived from the mode and the
 * latest heartbeat. "invisible" plays normally but looks offline, like in League of Legends.
 */
export const PRESENCE_MODES = ['online', 'away', 'busy', 'invisible'] as const;
export type PresenceMode = (typeof PRESENCE_MODES)[number];

export type PresenceStatus = 'online' | 'away' | 'busy' | 'offline';

/** Room codes are generated by the room browser: letters and digits. */
const ROOM_CODE_PATTERN = /^[A-Za-z0-9_-]{3,32}$/;

/** Secret reconnect ids are generated by the browser (uuid-like). */
const SEAT_PROOF_PATTERN = /^[A-Za-z0-9_-]{8,128}$/;

export type PresenceActivity =
  | { kind: 'menu' }
  /** `gamePlayerId` is the seat the game worker attested (null while unverified). */
  | { kind: 'lobby'; roomCode: string; gamePlayerId: string | null }
  | { kind: 'game'; roomCode: string; gamePlayerId: string | null };

/** What a client reports with every heartbeat. */
export interface PresenceHeartbeat {
  mode: PresenceMode;
  activity: PresenceActivity;
  /** The tab is hidden: an "online" player is shown as away. */
  idle: boolean;
  at: number;
}

/** What friends see. The room code is only shared while the lobby can be joined. */
export interface FriendPresence {
  status: PresenceStatus;
  activity: 'menu' | 'lobby' | 'game' | null;
  joinableRoomCode: string | null;
  since: number | null;
}

export const OFFLINE_PRESENCE: FriendPresence = Object.freeze({ status: 'offline', activity: null, joinableRoomCode: null, since: null });

export function isPresenceMode(value: unknown): value is PresenceMode {
  return typeof value === 'string' && (PRESENCE_MODES as readonly string[]).includes(value);
}

export function isRoomCode(value: unknown): value is string {
  return typeof value === 'string' && ROOM_CODE_PATTERN.test(value);
}

export function isSeatProof(value: unknown): value is string {
  return typeof value === 'string' && SEAT_PROOF_PATTERN.test(value);
}

/**
 * Parses an untrusted activity; anything malformed counts as being in the menus. A client never
 * names its seat: that comes from the worker's attestation.
 */
export function parsePresenceActivity(value: unknown): PresenceActivity {
  if (typeof value !== 'object' || value === null) return { kind: 'menu' };
  const { kind, roomCode } = value as { kind?: unknown; roomCode?: unknown };
  if ((kind !== 'lobby' && kind !== 'game') || !isRoomCode(roomCode)) return { kind: 'menu' };
  return { kind, roomCode, gamePlayerId: null };
}

function statusOf(heartbeat: PresenceHeartbeat): PresenceStatus {
  if (heartbeat.mode === 'invisible') return 'offline';
  if (heartbeat.mode === 'busy') return 'busy';
  if (heartbeat.mode === 'away' || heartbeat.idle) return 'away';
  return 'online';
}

/** The presence a friend sees for a heartbeat (null: no live heartbeat). */
export function presenceForFriends(heartbeat: PresenceHeartbeat | null): FriendPresence {
  if (!heartbeat) return OFFLINE_PRESENCE;
  const status = statusOf(heartbeat);
  if (status === 'offline') return OFFLINE_PRESENCE;
  const { activity } = heartbeat;
  return {
    status,
    activity: activity.kind,
    joinableRoomCode: activity.kind === 'lobby' ? activity.roomCode : null,
    since: heartbeat.at,
  };
}

/** Sort weight for friend lists: playing friends first, offline last. */
export function presenceRank(presence: FriendPresence): number {
  if (presence.status === 'offline') return 4;
  if (presence.status === 'away') return 3;
  if (presence.activity === 'lobby') return 0;
  if (presence.activity === 'game') return 1;
  return 2;
}
